class SimpleList {
  private items: number[] = [1, 2, 3];
  iterator() {
    let index = 0;
    const items = this.items;
    return {
      next() {
        if (index >= items.length) return { done: true };
        return { value: items[index++], done: false };
      },
      hasNext() { return index < items.length; }
    };
  }
}

class ProductList {
  private products: string[] = ['a', 'b', 'c'];
  private sharedIter = {
    index: 0,
    next: () => {
      const i = (this as any).sharedIter.index;
      if (i >= this.products.length) return { done: true };
      (this as any).sharedIter.index = i + 1;
      return { value: this.products[i], done: false };
    }
  };
  getIterator() { return this.sharedIter; }
}

